      old_instruction, new_instruction,
      /*preserve_sharding=*/false, preserve_frontend_attributes);
  if (ABSL_PREDICT_TRUE(changed_or.ok())) {
    DCHECK(changed_or.value());
  }
  return changed_or.status();
}

